#include <stdio.h>
#include <math.h>

typedef struct { float x,y,z; } V;

static V vsub(V a, V b){ V r={a.x-b.x,a.y-b.y,a.z-b.z}; return r; }
static float vdot(V a, V b){ return (a.x*b.x + a.y*b.y) + a.z*b.z; }
static V vnorm(V v){ float l=sqrtf((v.x*v.x+v.y*v.y)+v.z*v.z); V r={v.x/l,v.y/l,v.z/l}; return r; }

static const V SC = {0.0f,-0.5f,-5.0f};
#define SR 1.0f

typedef struct { float t; V p; V n; int hit; } Hit;

static Hit sphere_hit(V o, V d){
  Hit h; h.hit=0; h.t=0.0f; h.p=(V){0,0,0}; h.n=(V){0,0,0};
  V oc = vsub(o, SC);
  float a = (d.x*d.x + d.y*d.y) + d.z*d.z;
  float b = 2.0f*((oc.x*d.x + oc.y*d.y) + oc.z*d.z);
  float c = ((oc.x*oc.x + oc.y*oc.y) + oc.z*oc.z) - SR*SR;
  float disc = b*b - (4.0f*a)*c;
  if (disc < 0.0f) return h;
  double nb = -(double)b;
  double sq = sqrt((double)disc);
  double twoa = (double)(2.0f*a);
  float t = (float)((nb - sq)/twoa);
  if (!(t >= 0.001f)) {
    t = (float)((nb + sq)/twoa);
    if (!(t >= 0.001f)) return h;
  }
  h.hit=1; h.t=t;
  h.p=(V){o.x+d.x*t, o.y+d.y*t, o.z+d.z*t};
  h.n=vnorm(vsub(h.p, SC));
  return h;
}

static V sky(V d){
  float t = (d.y + 1.0f) * 0.5f;
  V r;
  r.x = 0.5f*t + (1.0f - t);
  r.y = 0.7f*t + (1.0f - t);
  r.z = (1.0f - t) + t;
  return r;
}

static float shade(V p, V n, V L, V Lsh){
  Hit s = sphere_hit(p, Lsh);
  if (s.hit) return 0.2f;
  float dot = vdot(n, L);
  return (float)fmax(0.0, (double)dot) * 0.8f + 0.2f;
}

static V trace(V o, V d, V L, V Lsh){
  Hit sh = sphere_hit(o, d);
  int plane_hit = 0; float tp = 0.0f;
  if (fabsf(d.y) >= 0.0001f){
    tp = (-1.5f - o.y)/d.y;
    if (tp >= 0.001f) plane_hit = 1;
  }
  int use_sphere;
  if (sh.hit && plane_hit) use_sphere = (tp > sh.t);
  else if (sh.hit) use_sphere = 1;
  else if (plane_hit) use_sphere = 0;
  else return sky(d);
  float b;
  if (use_sphere){
    b = shade(sh.p, sh.n, L, Lsh);
    return (V){b, 0.2f*b, 0.2f*b};
  } else {
    V p = (V){o.x+d.x*tp, o.y+d.y*tp, o.z+d.z*tp};
    V n = (V){0.0f,1.0f,0.0f};
    b = shade(p, n, L, Lsh);
    long s = (long)((double)floorf(p.x) + (double)floorf(p.z));
    float c = (s & 1) ? 0.4f : 0.9f;
    return (V){c*b, c*b, c*b};
  }
}

static int px(float c){
  union { unsigned u; float f; } sc = { 0x437ffd71u };
  return (int)((float)fmin(1.0, fmax((double)c, 0.0)) * sc.f);
}

int main(void){
  const int W = 800, H = 600;
  fprintf(stderr, "Creating high-resolution image: %dx%d\n", W, H);
  fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");
  V L = vnorm((V){1.0f,1.0f,-1.0f});
  V Lsh = vnorm(L);
  float **img = malloc(H * sizeof(float*));
  for (int y=0; y<H; y++) img[y] = malloc(W*3*sizeof(float));
  fprintf(stderr, "Rendering high-resolution image...\n");
  V o = {0.0f,0.0f,0.0f};
  for (int y=0; y<H; y++){
    fprintf(stderr, "\rProgress: %.1f%%", (double)(100.0f*(float)y/600.0f));
    float vrow = (1.0f - ((float)y/599.0f)) + (1.0f - ((float)y/599.0f));
    float *row = img[y];
    for (int x=0; x<W; x++){
      float u = ((float)x/799.0f) * 2.6666667f;
      V d;
      d.x = (u + 0.0f) - 1.3333334f;
      d.y = (0.0f + vrow) - 1.0f;
      d.z = 0.0f - 1.0f;
      d = vnorm(d);
      V col = trace(o, d, L, Lsh);
      row[x*3+0] = col.x;
      row[x*3+1] = col.y;
      row[x*3+2] = col.z;
    }
  }
  fprintf(stderr, "\nRendering complete\n");
  FILE *f = fopen("image.ppm", "w");
  fprintf(f, "P3\n%d %d\n255\n", W, H);
  for (int y=0; y<H; y++){
    float *row = img[y];
    for (int x=0; x<W; x++)
      fprintf(f, "%d %d %d\n", px(row[x*3+0]), px(row[x*3+1]), px(row[x*3+2]));
  }
  fclose(f);
  fprintf(stderr, "Wrote image to %s\n", "image.ppm");
  for (int y=0; y<H; y++) free(img[y]);
  free(img);
  fprintf(stderr, "Done.\n");
  return 0;
}

